lesson(ch, "shapes", "Shapes: circle, square, triangle, rectangle", ["Name four flat shapes.", "Count sides and corners."],
  [("definition", "Flat shapes", "A **circle** is round. It has no corners. A **triangle** has 3 sides. A **square** has 4 sides that are all the same. A **rectangle** has 4 sides: two long and two short."),
   ("retenir", "Look around", "A plate is a circle. A window can be a rectangle. A roof end can be a triangle. A tile can be a square."),
   ("pieges", "Common mistakes", "- A square is not a triangle.\n- A rectangle has two long and two short sides.\n- A circle has no sides to count.")],
  [("Example 1", "How many sides has a triangle?", ["Touch each side of the triangle.", "There are three."], "3 sides", shapes([POLY([30, 100, 130, 100, 80, 20], fill="lightyellow")], 160, 120)),
   ("Example 2", "Which shape is a plate?", ["A plate is round.", "A round shape is a circle."], "A circle", None)],
  (sq, "Four shapes.", "A blue square, a green circle, a yellow triangle and a pink rectangle, each with its name."),
  [("n", "How many sides has a square?", 4, "A square has 4 sides."),
   ("m", "Which shape has 3 sides?", "triangle", ["circle", "square", "rectangle"], "A triangle has three sides."),
   ("m", "Which shape is round?", "circle", ["square", "triangle", "rectangle"], "A circle is round.")],
  [("x", "Match the shape and the thing.", [("circle", "a plate"), ("rectangle", "a door"), ("square", "a floor tile"), ("triangle", "a slice of pizza")], "Look at the outline of each thing."),
   ("t", "A rectangle has 4 sides.", True, "It has 4 sides and 4 corners.")],
  ("p", "Sali draws shapes on her slate.", [("n", "She draws 2 squares. How many sides in all? (4 + 4)", 8, "4 + 4 = 8."), ("n", "She draws 3 triangles. How many sides in all? (3 + 3 + 3)", 9, "3 + 3 + 3 = 9.")]),
  [("Class 1 maths shapes: which shape has no corners?", "circle", ["square", "triangle", "rectangle"], "A circle is round with no corners."),
   ("A triangle has how many corners?", "3", ["4", "2", "0"], "Three corners."),
   ("Which shape has 4 equal sides?", "square", ["triangle", "circle", "none"], "All sides of a square are equal."),
   ("A football looks like a...", "circle (round)", ["triangle", "square", "line"], "It is round."),
   ("A door is often a...", "rectangle", ["circle", "triangle", "heart"], "A door is long and has 4 corners.")],
  ["Solid shapes (sphere, cube) are left for Class 2."])

lesson(ch, "length", "Long, short and how long", ["Say long, short, tall and short.", "Measure with hand spans and a ruler in cm."],
  [("definition", "Length", "We say a thing is **long** or **short**. A person can be **tall** or **short**. We measure length with a ruler. We use **centimetres** (cm)."),
   ("methode", "Use a ruler", "Put the zero of the ruler at the start of the thing. Look where the thing ends. Read the number. Say the number with cm."),
   ("pieges", "Common mistakes", "- Start at 0, not at the edge of the ruler.\n- Do not leave a gap.\n- Say the unit: cm.")],
  [("Example 1", "A pencil goes from 0 to 8 on the ruler. How long is it?", ["It starts at 0.", "It ends at 8. It is 8 cm long."], "8 cm", shapes([RECT(10, 40, 380, 40, fill="lightyellow")] + [LINE(10 + i * 38, 40, 10 + i * 38, 62 if i % 5 else 70, width=2) for i in range(11)] + [T(10 + i * 38, 100, str(i), 12) for i in range(0, 11, 2)] + [RECT(10, 6, 8 * 38, 22, fill="orange", radius=5)], 400, 112)),
   ("Example 2", "A rope is 5 cm. A stick is 9 cm. Which is longer?", ["Compare 5 and 9.", "9 is bigger."], "The stick", None)],
  (shapes([RECT(20, 20, 300, 24, fill="orange", radius=6), T(20, 70, "long", 14, anchor="start", bold=True), RECT(20, 90, 120, 24, fill="lightgreen", radius=6), T(20, 140, "short", 14, anchor="start", bold=True)], 360, 150), "A long bar and a short bar.", "An orange long bar and a green short bar."),
  [("m", "Which is longer: a road or a pencil?", "a road", ["a pencil", "the same", "none"], "A road is much longer."),
   ("n", "A line is from 0 to 6 on a ruler. How many cm?", 6, "It is 6 cm.", "cm"),
   ("t", "We measure length with a ruler.", True, "A ruler has cm marks.")],
  [("m", "Which unit do we use for a pencil?", "cm", ["litres", "FCFA", "days"], "cm is for short lengths."), ("m", "Which is shortest: 12 cm, 7 cm or 15 cm?", "7 cm", ["12 cm", "15 cm", "same"], "7 is the smallest number.")],
  ("p", "Pupils measure things in class.", [("n", "A book is 20 cm long. A pen is 14 cm long. How much longer is the book? (20 − 14)", 6, "20 − 14 = 6 cm.", "cm"), ("m", "Which is longer?", "the book", ["the pen", "same", "none"], "20 is more than 14.")]),
  [("Class 1 maths length: we measure length in...", "centimetres", ["litres", "kilograms", "hours"], "Length uses cm."),
   ("A giraffe is...", "tall", ["round", "heavy only", "cold"], "A giraffe is very tall."),
   ("Where do we put a ruler to start?", "at zero", ["at ten", "in the middle", "anywhere"], "Start at 0."),
   ("Which is longer: 9 cm or 4 cm?", "9 cm", ["4 cm", "same", "none"], "9 is more than 4."),
   ("A pencil is about 15...", "cm", ["litres", "FCFA", "kg"], "We use cm for a pencil.")],
  ["cm only; metres are left for Class 2-3."])

lesson(ch, "heavy-light", "Heavy and light, full and empty", ["Say which thing is heavy or light.", "Say full, empty and half full."],
  [("definition", "Heavy and light", "A **heavy** thing is hard to lift. A **light** thing is easy to lift. A bag of cement is heavy. A feather is light."),
   ("retenir", "Full and empty", "A cup with no water is **empty**. A cup with water to the top is **full**. A cup with water to the middle is **half full**."),
   ("pieges", "Common mistakes", "- A big thing is not always heavy.\n- A small stone can be heavier than a big balloon.\n- Half full is not empty.")],
  [("Example 1", "Which is heavier: a stone or a leaf?", ["Lift a stone. Lift a leaf.", "The stone is hard to lift."], "The stone", None),
   ("Example 2", "A bucket has water to the top. Is it full or empty?", ["Look at the water.", "It is at the top, so it is full."], "Full", None)],
  (shapes([RECT(30, 40, 60, 80, fill="white"), RECT(30, 120 - 80, 60, 80, stroke="ink"), T(60, 140, "full", 14, bold=True), RECT(160, 40, 60, 80, fill="white"), RECT(160, 80, 60, 40, fill="lightblue"), T(190, 140, "half", 14, bold=True), RECT(290, 40, 60, 80, fill="white"), T(320, 140, "empty", 14, bold=True)] , 380, 160), "Full, half full and empty.", "Three cups: one full, one half full and one empty."),
  [("m", "Which is heavy?", "a bag of cement", ["a feather", "a leaf", "a paper"], "Cement is heavy."),
   ("m", "Which is light?", "a feather", ["a big stone", "a bag of sand", "a car"], "A feather is light."),
   ("t", "An empty cup has no water.", True, "Empty means nothing inside.")],
  [("x", "Match.", [("a cup with no water", "empty"), ("a cup to the top", "full"), ("a bag of sand", "heavy"), ("a feather", "light")], "Think about each thing."),
   ("m", "Which cup has more water: full or half full?", "full", ["half full", "empty", "same"], "Full has most.")],
  ("p", "Mama is at the market with a basket.", [("m", "The basket has yams. It is hard to lift. Is it heavy or light?", "heavy", ["light", "empty", "tiny"], "Hard to lift means heavy."), ("m", "She takes out all the yams. Now the basket is...", "empty", ["full", "heavy", "half full"], "Nothing is inside.")]),
  [("Class 1 maths: a thing that is easy to lift is...", "light", ["heavy", "full", "long"], "Light is easy to lift."),
   ("A bucket with water to the top is...", "full", ["empty", "half full", "short"], "Full."),
   ("Which is heavier: a stone or a piece of paper?", "a stone", ["a piece of paper", "the same", "none"], "A stone is heavier."),
   ("A jug with no water is...", "empty", ["full", "heavy", "tall"], "Empty."),
   ("Half full means water up to the...", "middle", ["top", "bottom only", "lid"], "Half is the middle.")],
  ["Informal comparison only; no kilograms or litres in Class 1."])

# ===================================================== money & time
ch = p.chapter("money-time", "Money and time", R)
coins = shapes([CIRCLE(40, 45, 28, fill="lightyellow"), T(40, 50, "50", 16, bold=True), CIRCLE(110, 45, 28, fill="lightyellow"), T(110, 50, "100", 16, bold=True),
                CIRCLE(180, 45, 28, fill="lightyellow"), T(180, 50, "500", 16, bold=True), RECT(230, 20, 70, 50, fill="lightgreen", radius=4), T(265, 50, "1000", 14, bold=True),
                RECT(310, 20, 70, 50, fill="lightblue", radius=4), T(345, 50, "2000", 14, bold=True), T(40, 100, "coin", 13), T(110, 100, "coin", 13), T(180, 100, "coin", 13), T(265, 100, "note", 13), T(345, 100, "note", 13)], 400, 115)
lesson(ch, "fcfa-money", "FCFA coins and notes", ["Name some FCFA coins and notes.", "Add small amounts of money."],
  [("definition", "Money", "In Cameroon we use **FCFA** (francs CFA). We pay with **coins** and **notes**. We buy things at the shop and at the market."),
   ("retenir", "Coins and notes", "Some coins are 5, 10, 25, 50, 100 and 500 FCFA. Some notes are 1000, 2000, 5000 and 10 000 FCFA. A note is worth more than a small coin."),
   ("pieges", "Common mistakes", "- A big coin is not always worth more. Read the number.\n- Say FCFA after the number.\n- Do not mix the coins and the notes.")],
  [("Example 1", "A pencil costs 50 FCFA. A rubber costs 50 FCFA. How much for both?", ["Add 50 and 50.", "50 + 50 = 100."], "100 FCFA", None),
   ("Example 2", "You have a 100 FCFA coin. A sweet costs 25 FCFA. Can you buy it?", ["100 is more than 25.", "Yes, you can buy it."], "Yes", None)],
  (coins, "Some FCFA coins and notes (not to scale).", "Three coins marked 50, 100 and 500, and two notes marked 1000 and 2000."),
  [("n", "A banana costs 10 FCFA. You buy 2. How many FCFA? (10 + 10)", 20, "10 + 10 = 20.", "FCFA"),
   ("m", "Which is worth the most?", "1000 FCFA", ["100 FCFA", "50 FCFA", "10 FCFA"], "1000 is the biggest number."),
   ("n", "Two coins of 100 FCFA make how many FCFA?", 200, "100 + 100 = 200.", "FCFA")],
  [("n", "A sweet costs 25 FCFA. You pay 50 FCFA. How much do you get back? (50 − 25)", 25, "50 − 25 = 25.", "FCFA"), ("t", "500 FCFA is more than 100 FCFA.", True, "500 is bigger than 100.")],
  ("p", "Ebai goes to the shop in Bamenda.", [("n", "A biscuit costs 100 FCFA. A sweet costs 25 FCFA. How much in all?", 125, "100 + 25 = 125.", "FCFA"), ("n", "He pays with 200 FCFA. How much does he get back?", 75, "200 − 125 = 75.", "FCFA")]),
  [("Class 1 maths money: the money used in Cameroon is...", "FCFA", ["dollar", "pound", "shilling"], "FCFA."),
   ("Which is a note?", "1000 FCFA", ["100 FCFA coin", "50 FCFA coin", "25 FCFA coin"], "1000 is usually a note."),
   ("50 FCFA and 50 FCFA make...", "100 FCFA", ["500 FCFA", "55 FCFA", "10 FCFA"], "50 + 50 = 100."),
   ("We pay for things with...", "coins and notes", ["leaves", "stones", "water"], "We use money."),
   ("Which is the most money?", "500 FCFA", ["50 FCFA", "100 FCFA", "25 FCFA"], "500 is biggest.")],
  ["Check which coins and notes are used in schools today; amounts are to be kept small; no change rules beyond easy subtraction."])

lesson(ch, "days-weeks", "Days of the week and months", ["Say the seven days in order.", "Say the months of the year."],
  [("definition", "The week", "There are **7 days** in a week: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday. We go to school on weekdays, Monday to Friday."),
   ("retenir", "The year", "There are **12 months** in a year: January, February, March, April, May, June, July, August, September, October, November, December."),
   ("pieges", "Common mistakes", "- After Sunday comes Monday.\n- Yesterday is before today. Tomorrow is after today.\n- A week has 7 days, not 5.")],
  [("Example 1", "Today is Tuesday. What day is tomorrow?", ["After Tuesday comes Wednesday.", "Tomorrow is Wednesday."], "Wednesday", None),
   ("Example 2", "How many school days are there in a week (Monday to Friday)?", ["Count: Monday, Tuesday, Wednesday, Thursday, Friday.", "That is 5 days."], "5 days", None)],
  (cards(["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"], 4, 400, ch=34), "The seven days.", "Seven boxes with the days of the week."),
  [("m", "Which day comes after Friday?", "Saturday", ["Thursday", "Monday", "Sunday"], "Saturday follows Friday."),
   ("n", "How many days are in a week?", 7, "Seven days."),
   ("n", "How many months are in a year?", 12, "Twelve months.")],
  [("m", "Which day is before Wednesday?", "Tuesday", ["Thursday", "Friday", "Sunday"], "Tuesday comes before."), ("x", "Match.", [("first day of the school week", "Monday"), ("last school day", "Friday"), ("day after Saturday", "Sunday"), ("month after January", "February")], "Say them in order.")],
  ("p", "Nkeng goes to school from Monday to Friday.", [("n", "How many days does he go to school in one week?", 5, "Monday to Friday is 5 days."), ("n", "How many days are the weekend? (Saturday and Sunday)", 2, "Two days.")]),
  [("Class 1 maths time: the day after Monday is...", "Tuesday", ["Sunday", "Wednesday", "Friday"], "Tuesday."),
   ("How many days are there in a week?", "7", ["5", "10", "12"], "Seven."),
   ("Which is the first month of the year?", "January", ["March", "December", "June"], "January."),
   ("Yesterday is...", "the day before today", ["the day after today", "next week", "last year"], "Before today."),
   ("The weekend days are...", "Saturday and Sunday", ["Monday and Tuesday", "Friday and Monday", "Wednesday and Thursday"], "Saturday and Sunday.")],
  ["School days and months are standard; the school year dates are not given."])

lesson(ch, "time-oclock", "Telling the time: o'clock", ["Read the hour on a clock.", "Say the time to the hour."],
  [("definition", "The clock", "A clock has a **short hand** and a **long hand**. The short hand shows the **hour**. When the long hand points to 12, it is **o'clock**."),
   ("retenir", "Read the hour", "Long hand on 12. Short hand on 3. It is 3 o'clock. Short hand on 7 is 7 o'clock."),
   ("pieges", "Common mistakes", "- The short hand shows the hour.\n- The long hand on 12 means o'clock.\n- Do not mix up the two hands.")],
  [("Example 1", "The long hand is on 12. The short hand is on 4. What time is it?", ["Long hand on 12 means o'clock.", "The short hand is on 4. It is 4 o'clock."], "4 o'clock", clockface(4, 0)),
   ("Example 2", "School starts at 8 o'clock. Where is the short hand?", ["It is at 8.", "The long hand is at 12."], "On the 8", clockface(8, 0))],
  (clockface(3, 0), "This clock shows 3 o'clock.", "A clock face with the short red hand on 3 and the long blue hand on 12."),
  [("m", "The clock shows this time.", "6 o'clock", ["5 o'clock", "7 o'clock", "12 o'clock"], "Short hand on 6.", {"figure": clockface(6, 0)}),
   ("m", "What time is shown?", "9 o'clock", ["3 o'clock", "12 o'clock", "10 o'clock"], "Short hand on 9.", {"figure": clockface(9, 0)}),
   ("t", "The short hand shows the hour.", True, "Yes, it shows the hour.")],
  [("n", "Short hand on 2, long hand on 12. It is __ o'clock.", 2, "2 o'clock."), ("n", "School starts at 8 and ends at 12. How many hours is that? (12 − 8)", 4, "4 hours.")],
  ("p", "Mama's day at the market.", [("m", "She opens at 7 o'clock. Where is the short hand?", "on 7", ["on 12", "on 5", "on 9"], "7 o'clock."), ("n", "She closes at 6 o'clock in the evening. What number is the short hand on?", 6, "On the 6.")]),
  [("Class 1 maths time: which hand shows the hour?", "the short hand", ["the long hand", "both", "none"], "The short hand."),
   ("When the long hand is on 12, we say...", "o'clock", ["half past", "midnight only", "quarter"], "It is o'clock."),
   ("The short hand is on 5. The long hand is on 12. The time is...", "5 o'clock", ["12 o'clock", "6 o'clock", "1 o'clock"], "5 o'clock."),
   ("How many numbers are on a clock face?", "12", ["10", "7", "24"], "Twelve."),
   ("How many hours are there from 3 o'clock to 5 o'clock?", "2", ["1", "3", "8"], "5 − 3 = 2.")],
  ["Half past and quarter past are in Class 2."], prereq=["class1-maths-days-weeks"])

p.write()
